import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import API from '../services/api';

export default function UploadDocument() {
  const [form, setForm] = useState({ title: '', category: '', department: '', tags: '', notes: '' });
  const [file, setFile] = useState(null);
  const [categories, setCategories] = useState([]);
  const [newCategory, setNewCategory] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const navigate = useNavigate();

  useEffect(() => { API.get('/categories').then(r => setCategories(r.data)).catch(() => {}); }, []);

  const handleAddCategory = async () => {
    if (!newCategory.trim()) return;
    try {
      const { data } = await API.post('/categories', { name: newCategory });
      setCategories([...categories, data]);
      setForm({ ...form, category: data._id });
      setNewCategory('');
    } catch (err) { setError(err.response?.data?.message || 'Failed to create category'); }
  };

  const handleDrop = (e) => {
    e.preventDefault(); setDragOver(false);
    const dropped = e.dataTransfer.files[0];
    if (dropped) setFile(dropped);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!file) return setError('Please select a file');
    setError(''); setSuccess(''); setLoading(true);
    try {
      const fd = new FormData();
      Object.entries(form).forEach(([k, v]) => fd.append(k, v));
      fd.append('file', file);
      await API.post('/documents', fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      setSuccess('Document uploaded successfully!');
      setTimeout(() => navigate('/documents'), 1500);
    } catch (err) {
      setError(err.response?.data?.message || 'Upload failed');
    } finally { setLoading(false); }
  };

  const fileIcon = file ? ({ 'application/pdf': '📕', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document': '📘', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': '📗' }[file.type] || '🖼') : null;

  return (
    <div style={styles.page}>
      <div style={styles.header}>
        <h1 style={styles.title}>Upload Document</h1>
        <p style={styles.sub}>Add a new document to the records management system</p>
      </div>

      <div style={styles.layout}>
        <form onSubmit={handleSubmit} style={styles.form}>
          {error && <div style={styles.errorBox}>⚠️ {error}</div>}
          {success && <div style={styles.successBox}>✅ {success}</div>}

          <div style={styles.section}>
            <h3 style={styles.sectionTitle}>📋 Document Details</h3>
            <div style={styles.field}>
              <label style={styles.label}>Title <span style={styles.req}>*</span></label>
              <input style={styles.input} placeholder="Enter document title" value={form.title}
                onChange={e => setForm({ ...form, title: e.target.value })} required />
            </div>
            <div style={styles.grid2}>
              <div style={styles.field}>
                <label style={styles.label}>Department <span style={styles.req}>*</span></label>
                <input style={styles.input} placeholder="e.g. Finance, HR, IT" value={form.department}
                  onChange={e => setForm({ ...form, department: e.target.value })} required />
              </div>
              <div style={styles.field}>
                <label style={styles.label}>Tags</label>
                <input style={styles.input} placeholder="e.g. report, 2024, annual" value={form.tags}
                  onChange={e => setForm({ ...form, tags: e.target.value })} />
              </div>
            </div>
          </div>

          <div style={styles.section}>
            <h3 style={styles.sectionTitle}>🗂 Category</h3>
            <div style={styles.field}>
              <label style={styles.label}>Select Category</label>
              <select style={styles.input} value={form.category} onChange={e => setForm({ ...form, category: e.target.value })}>
                <option value="">-- Select Category --</option>
                {categories.map(c => <option key={c._id} value={c._id}>{c.name}</option>)}
              </select>
            </div>
            <div style={styles.field}>
              <label style={styles.label}>Or Create New Category</label>
              <div style={styles.catRow}>
                <input style={{ ...styles.input, marginBottom: 0, flex: 1 }} placeholder="New category name"
                  value={newCategory} onChange={e => setNewCategory(e.target.value)} />
                <button type="button" onClick={handleAddCategory} style={styles.addCatBtn}>+ Add</button>
              </div>
            </div>
          </div>

          <div style={styles.section}>
            <h3 style={styles.sectionTitle}>📝 Version Notes</h3>
            <div style={styles.field}>
              <label style={styles.label}>Notes for this version</label>
              <input style={styles.input} placeholder="Describe what's in this version..." value={form.notes}
                onChange={e => setForm({ ...form, notes: e.target.value })} />
            </div>
          </div>

          <button style={{ ...styles.submitBtn, opacity: loading ? 0.7 : 1 }} type="submit" disabled={loading}>
            {loading ? '⏳ Uploading...' : '⬆  Upload Document'}
          </button>
        </form>

        {/* File Drop Zone */}
        <div style={styles.sidebar}>
          <div style={styles.section}>
            <h3 style={styles.sectionTitle}>📁 Select File</h3>
            <div style={{ ...styles.dropZone, ...(dragOver ? styles.dropZoneActive : {}) }}
              onDragOver={e => { e.preventDefault(); setDragOver(true); }}
              onDragLeave={() => setDragOver(false)}
              onDrop={handleDrop}
              onClick={() => document.getElementById('fileInput').click()}>
              {file ? (
                <div style={styles.filePreview}>
                  <span style={{ fontSize: '40px' }}>{fileIcon}</span>
                  <p style={styles.fileName}>{file.name}</p>
                  <p style={styles.fileSize}>{(file.size / 1024).toFixed(1)} KB</p>
                  <button type="button" style={styles.removeFile} onClick={e => { e.stopPropagation(); setFile(null); }}>✕ Remove</button>
                </div>
              ) : (
                <div style={styles.dropContent}>
                  <span style={{ fontSize: '40px' }}>📂</span>
                  <p style={styles.dropText}>Drag & drop file here</p>
                  <p style={styles.dropSub}>or click to browse</p>
                </div>
              )}
            </div>
            <input id="fileInput" type="file" accept=".pdf,.docx,.xlsx,.jpg,.jpeg"
              style={{ display: 'none' }} onChange={e => setFile(e.target.files[0])} />
            <div style={styles.allowedTypes}>
              {['PDF', 'DOCX', 'XLSX', 'JPG'].map(t => (
                <span key={t} style={styles.typeTag}>{t}</span>
              ))}
              <span style={styles.maxSize}>Max 10MB</span>
            </div>
          </div>

          <div style={styles.section}>
            <h3 style={styles.sectionTitle}>ℹ️ Upload Guidelines</h3>
            <ul style={styles.guidelines}>
              <li>Use descriptive titles for easy retrieval</li>
              <li>Assign correct department for filtering</li>
              <li>Add relevant tags for better search</li>
              <li>Maximum file size is 10MB</li>
              <li>Supported: PDF, DOCX, XLSX, JPG</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
}

const styles = {
  page: { padding: '28px', maxWidth: '1100px', margin: '0 auto' },
  header: { marginBottom: '24px' },
  title: { fontSize: '24px', fontWeight: '700', color: '#1e293b', marginBottom: '4px' },
  sub: { color: '#64748b', fontSize: '14px' },
  layout: { display: 'grid', gridTemplateColumns: '1fr 340px', gap: '20px' },
  form: {},
  section: { background: '#fff', borderRadius: '12px', padding: '20px', boxShadow: '0 1px 3px rgba(0,0,0,0.06)', marginBottom: '16px' },
  sectionTitle: { fontSize: '14px', fontWeight: '600', color: '#374151', marginBottom: '16px', paddingBottom: '10px', borderBottom: '1px solid #f1f5f9' },
  field: { marginBottom: '14px' },
  label: { display: 'block', fontSize: '13px', fontWeight: '600', color: '#374151', marginBottom: '6px' },
  req: { color: '#ef4444' },
  input: { display: 'block', width: '100%', padding: '10px 12px', border: '1.5px solid #e2e8f0', borderRadius: '8px', fontSize: '14px', outline: 'none', background: '#f8fafc', boxSizing: 'border-box', marginBottom: '0' },
  grid2: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '14px' },
  catRow: { display: 'flex', gap: '8px' },
  addCatBtn: { padding: '10px 16px', background: '#4f46e5', color: '#fff', border: 'none', borderRadius: '8px', cursor: 'pointer', fontSize: '13px', fontWeight: '600', whiteSpace: 'nowrap' },
  submitBtn: { width: '100%', padding: '13px', background: 'linear-gradient(135deg, #4f46e5, #7c3aed)', color: '#fff', border: 'none', borderRadius: '10px', fontSize: '15px', fontWeight: '600', cursor: 'pointer' },
  errorBox: { background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '12px 16px', borderRadius: '8px', fontSize: '13px', marginBottom: '16px' },
  successBox: { background: '#f0fdf4', border: '1px solid #bbf7d0', color: '#166534', padding: '12px 16px', borderRadius: '8px', fontSize: '13px', marginBottom: '16px' },
  sidebar: {},
  dropZone: { border: '2px dashed #e2e8f0', borderRadius: '12px', padding: '32px 20px', textAlign: 'center', cursor: 'pointer', transition: 'all 0.2s', background: '#f8fafc', marginBottom: '12px' },
  dropZoneActive: { border: '2px dashed #4f46e5', background: '#f0f0ff' },
  dropContent: { display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' },
  dropText: { fontSize: '14px', fontWeight: '600', color: '#374151' },
  dropSub: { fontSize: '12px', color: '#94a3b8' },
  filePreview: { display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '6px' },
  fileName: { fontSize: '13px', fontWeight: '600', color: '#1e293b', wordBreak: 'break-all' },
  fileSize: { fontSize: '12px', color: '#94a3b8' },
  removeFile: { background: '#fef2f2', color: '#ef4444', border: '1px solid #fecaca', padding: '4px 12px', borderRadius: '6px', cursor: 'pointer', fontSize: '12px' },
  allowedTypes: { display: 'flex', gap: '6px', flexWrap: 'wrap', alignItems: 'center' },
  typeTag: { background: '#eff6ff', color: '#1d4ed8', padding: '3px 10px', borderRadius: '6px', fontSize: '11px', fontWeight: '600' },
  maxSize: { fontSize: '11px', color: '#94a3b8', marginLeft: 'auto' },
  guidelines: { paddingLeft: '18px', display: 'flex', flexDirection: 'column', gap: '8px', color: '#64748b', fontSize: '13px', lineHeight: '1.6' }
};
